[{"order":1,"type":"heading","text":"Server Actions and Form Handling in Next.js"},{"order":2,"type":"paragraph","text":"Server Actions in Next.js allow you to run asynchronous code directly on the server. They seamlessly integrate with forms, enabling progressive enhancement without needing to manually write API routes for every mutation."},{"order":3,"type":"subheading","text":"Understanding Server Actions"},{"order":4,"type":"paragraph","text":"A Server Action is defined using the 'use server' directive. You can place this directive at the top of an async function to designate it as a server-bound action, or at the top of a separate file to group multiple actions together."},{"order":5,"type":"code","text":"'use server';

export async function createUser(formData: FormData) {
  const name = formData.get('name');
  const email = formData.get('email');

  // Perform database operations here
  console.log('Creating user:', name, email);
}"},{"order":6,"type":"subheading","text":"Handling Forms with Server Actions"},{"order":7,"type":"paragraph","text":"To wire up a Server Action to a React form, pass the action to the action attribute of the form element. Next.js will automatically handle submitting the form data to the server."},{"order":8,"type":"code","text":"import { createUser } from '@/actions/user';

export default function SignupForm() {
  return (
    <form action={createUser}>
      <input type="text" name="name" placeholder="Your Name" required />
      <input type="email" name="email" placeholder="Your Email" required />
      <button type="submit">Sign Up</button>
    </form>
  );
}"},{"order":9,"type":"subheading","text":"Pending States with useFormStatus"},{"order":10,"type":"paragraph","text":"When submitting forms, providing visual feedback is essential. The useFormStatus hook allows you to track the pending state of a form submission to disable buttons or show loading spinners."},{"order":11,"type":"code","text":"'use client';

import { useFormStatus } from 'react-dom';

export function SubmitButton() {
  const { pending } = useFormStatus();

  return (
    <button type="submit" disabled={pending}>
      {pending ? 'Submitting...' : 'Submit'}
    </button>
  );
}"},{"order":12,"type":"subheading","text":"Best Practices"},{"order":13,"type":"bullet_point","text":"Always validate user input on the server side using libraries like Zod, even if client-side validation is present."},{"order":14,"type":"bullet_point","text":"Use revalidatePath or revalidateTag after a successful mutation to update cached data and keep the UI fresh."},{"order":15,"type":"bullet_point","text":"Keep Server Actions secure by checking user authentication and authorization parameters at the start of the function."}]
